function load(){try{return normalizeState(JSON.parse(localStorage.getItem(KEY))||{})}catch{return structuredClone(initial)}}
const RECEIPT_DB='society-gramado-receipts-v1';
function openReceiptDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(RECEIPT_DB,1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function saveLocalReceipt(file){if(file.size>5000000)throw new Error('O arquivo deve ter até 5 MB.');const db=await openReceiptDb(),key='r'+Date.now()+Math.random().toString(36).slice(2,7);await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();return key}
async function readLocalReceipt(key){const db=await openReceiptDb();const value=await new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return value}
function openReceipt(ref){const popup=window.open('about:blank','_blank');readLocalReceipt(ref.slice('localreceipt:'.length)).then(file=>{if(!file){popup?.close();toast('Este comprovante está salvo somente no dispositivo onde foi anexado.');return}const url=URL.createObjectURL(file);if(popup)popup.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60000)}).catch(()=>{popup?.close();toast('Não foi possível abrir o comprovante neste dispositivo.')})}
function receiptCell(p){if(!p.receipt)return '—';if(p.receipt.startsWith('localreceipt:'))return `<button type="button" class="link" data-action="open-receipt" data-receipt="${esc(p.receipt)}">Abrir arquivo ↗</button>`;return `<a class="link" href="${esc(p.receipt)}" target="_blank" rel="noopener">Ver arquivo ↗</a>`}
function persist(){localStorage.setItem(KEY,JSON.stringify(state)); saveAppData(state).then(()=>{syncPlayerSnapshots();syncPlayerLoginAliases();syncGameAwardBallots();syncGameRosters()}).catch(()=>toast('Não foi possível sincronizar com Firebase. Confira as regras do Firestore.'));}
function syncPlayerSnapshots(){if(!playerAccountsLoaded||!currentUser||!(firebaseConfig.adminUids||[firebaseConfig.adminUid]).includes(currentUser.uid))return;playerSyncPromise=playerSyncPromise.then(async()=>{for(const rec of playerAccounts){const player=state.players.find(p=>p.id===rec.playerId);if(player)await savePlayerData(rec.id,{...buildPlayerSnapshot(player),playerId:player.id,approved:true,attendanceChoices:rec.attendanceChoices||{}})}}).catch(()=>toast('Não foi possível atualizar os saldos dos jogadores.'));}
function syncGameRosters(){if(!appDataLoaded||!currentUser||currentUser.role!=='admin')return;for(const game of state.games.filter(item=>item.status!=='played'&&item.status!=='cancel')){const venue=field(game.fieldId);saveRecord('gameRosters',{id:game.id,date:game.date,time:game.time||'19:30',field:venue?.name||'Gramado',maps:venue?.maps||game.maps||'',waze:venue?.waze||game.waze||'',roster:(game.players||[]).map(player=>({name:player.name,position:player.position==='Goleiro'?'Goleiro':'Jogador'})),updatedAt:new Date().toISOString()}).catch(()=>toast('Não foi possível atualizar a lista dos jogadores.'));}}
function syncPlayerLoginAliases(){if(!playerAccountsLoaded||!accessRequestsLoaded||!loginAliasesLoaded||!currentUser||!(firebaseConfig.adminUids||[firebaseConfig.adminUid]).includes(currentUser.uid))return;loginAliasSyncPromise=loginAliasSyncPromise.then(async()=>{const expected=new Map();for(const rec of playerAccounts){if(!rec.approved)continue;const player=state.players.find(p=>p.id===rec.playerId);if(!player)continue;const request=accessRequests.find(r=>r.id===rec.id);const phone=request?.phone||rec.phone||player.phone;if(!phoneDigits(phone))continue;const firstName=request?.firstName||player.name.split(/\s+/)[0];const email=playerEmailFor(firstName,phone);const names=[player.name,player.nickname,...(player.aliases||[]),rec.name,rec.nickname,request?.firstName,request?.fullName,request?.nickname].filter(Boolean);for(const name of names){for(const alias of new Set([name,String(name).trim().split(/\s+/)[0]])){const id=await playerAliasId(alias,phone);expected.set(id,{id,email})}}}const saved=new Map(loginAliases.map(row=>[row.id,row.email]));for(const [id,row] of expected)if(saved.get(id)!==row.email)await saveRecord('playerLoginAliases',row)}).catch(()=>toast('Não foi possível sincronizar os nomes de acesso. Confira as regras do Firestore.'));}
function findParticipantForAccess(rec){const phone=rec.phone||'';const byPhone=state.players.filter(p=>phone&&p.phone&&playerPhoneMatches(phone,p.phone));if(byPhone.length===1)return byPhone[0];if(byPhone.length>1)return null;const keys=[rec.firstName,rec.fullName,rec.nickname,rec.name,rec.alias].filter(Boolean).map(playerKey);const exact=state.players.filter(p=>[p.name,p.nickname,...(p.aliases||[])].filter(Boolean).some(name=>keys.includes(playerKey(name))));return exact.length===1?exact[0]:null;}
async function attachPlayerAccount(rec,request){let player=findParticipantForAccess({...rec,...request});if(!player){let id=`p-${rec.id}`;if(state.players.some(p=>p.id===id))id=`${id}-${Date.now()}`;player={id,name:String(request?.fullName||request?.name||rec.name||request?.firstName||'Jogador').trim(),nickname:String(request?.nickname||rec.nickname||request?.fullName||rec.name||'').trim(),phone:String(request?.phone||rec.phone||''),active:true};state.players.push(player)}else{player.phone=player.phone||request?.phone||rec.phone||'';player.nickname=player.nickname||request?.nickname||rec.nickname||''}ensurePlayerInUpcomingGame(player);const linked={...rec,playerId:player.id,approved:true};await saveAppData(state);await savePlayerData(rec.id,{...buildPlayerSnapshot(player),playerId:player.id,approved:true,attendanceChoices:rec.attendanceChoices||{}});syncGameRosters();if(request&&request.status!=='approved')await saveRecord('playerAccessRequests',{...request,status:'approved'});playerAccounts=playerAccounts.map(x=>x.id===rec.id?linked:x);if(request)accessRequests=accessRequests.map(x=>x.id===request.id?{...request,status:'approved'}:x);syncPlayerSnapshots();localStorage.setItem(KEY,JSON.stringify(state));render();}
function processPlayerAccounts(){if(!appDataLoaded||!playerAccountsLoaded||!accessRequestsLoaded||!currentUser||!(firebaseConfig.adminUids||[firebaseConfig.adminUid]).includes(currentUser.uid))return;for(const request of accessRequests.filter(r=>r.status==='pending')){const rec=playerAccounts.find(x=>x.id===request.id)||{id:request.id,name:request.fullName||request.firstName,nickname:request.nickname,phone:request.phone,approved:true};if(autoApprovalInFlight.has(request.id))continue;autoApprovalInFlight.add(request.id);attachPlayerAccount(rec,request).then(()=>toast(`Acesso de ${request.fullName||request.firstName} liberado automaticamente.`)).catch(()=>toast('Não foi possível liberar o primeiro acesso. Confira as regras do Firestore.')).finally(()=>autoApprovalInFlight.delete(request.id));}for(const rec of playerAccounts.filter(x=>x.approved&&!x.playerId)){if(autoApprovalInFlight.has(rec.id))continue;autoApprovalInFlight.add(rec.id);attachPlayerAccount(rec,accessRequests.find(r=>r.id===rec.id)).catch(()=>toast('Não foi possível vincular o jogador ao elenco. Confira as regras do Firestore.')).finally(()=>autoApprovalInFlight.delete(rec.id));}}
function gameStartMillis(game){return Date.parse(`${game.date}T${game.time||'19:30'}:00-03:00`)}
function awardWindow(game){const start=gameStartMillis(game);return {opensAtMs:start+30*60000,closesAtMs:start+(Number(game.durationMinutes||60)+15)*60000}}
function presentPlayerIds(game){return new Set((game.players||[]).filter(p=>p.present).map(p=>p.playerId||findParticipantForEntry(p)?.id).filter(Boolean))}
function findParticipantForEntry(entry){return state.players.find(p=>p.id===entry.playerId||playerKey(p.name)===playerKey(entry.name))}
function awardTeamCandidates(game,team,index){const present=presentPlayerIds(game),ids=Array.isArray(team.playerIds)?team.playerIds.slice():((team.players||[]).map(name=>findTeamPlayer(name)?.id).filter(Boolean));const keeper=findTeamPlayer(team.goalkeeper)?.id;if(keeper)ids.push(keeper);return [...new Set(ids)].filter(id=>present.has(id)).map(id=>({id,name:state.players.find(p=>p.id===id)?.nickname||state.players.find(p=>p.id===id)?.name||'Jogador',goalkeeper:id===keeper}))}
function buildAwardBallot(game){const window=awardWindow(game),eligibleVoterIds=[...new Set(playerAccounts.filter(a=>a.approved!==false&&a.playerId&&(game.players||[]).some(p=>p.present&&(p.playerId===a.playerId||playerKey(p.name)===playerKey(state.players.find(x=>x.id===a.playerId)?.name||'')))).map(a=>a.id))];const teams=Object.fromEntries((game.teams||[]).slice(0,3).map((team,i)=>{const id=`team-${i+1}`,candidates=awardTeamCandidates(game,team,i);return [id,{id,name:team.name||`Time ${i+1}`,candidateIds:candidates.map(p=>p.id),candidates}]}));return {id:game.id,gameId:game.id,date:game.date,time:game.time||'19:30',opensAtMs:window.opensAtMs,closesAtMs:window.closesAtMs,opensAt:new Date(window.opensAtMs),closesAt:new Date(window.closesAtMs),eligibleVoterIds,teams}}
function syncGameAwardBallots(){if(!cloudEnabled||!appDataLoaded||!playerAccountsLoaded||!currentUser||!(firebaseConfig.adminUids||[firebaseConfig.adminUid]).includes(currentUser.uid))return;for(const game of state.games.filter(g=>g.status!=='played'&&g.status!=='cancel')){const ballot=buildAwardBallot(game),signature=JSON.stringify(ballot);if(awardBallotSignatures.get(game.id)===signature)continue;awardBallotSignatures.set(game.id,signature);saveRecord('gameAwardBallots',ballot).then(()=>{awardBallots=[...awardBallots.filter(x=>x.id!==ballot.id),ballot];if(page==='dashboard')render()}).catch(()=>{awardBallotSignatures.delete(game.id);toast('Não foi possível atualizar a votação do jogo. Verifique as regras do Firestore.')})}}
function voteWindowStatus(ballot,now=Date.now()){const opensAt=ballot.opensAtMs??ballot.opensAt?.toMillis?.()??Date.parse(ballot.opensAt),closesAt=ballot.closesAtMs??ballot.closesAt?.toMillis?.()??Date.parse(ballot.closesAt);if(now<opensAt)return 'before';if(now<=closesAt)return 'open';return 'closed'}
function ballotVotesFor(ballot,teamId){return awardVotes.filter(v=>v.gameId===ballot.gameId&&v.teamId===teamId)}
function winningCandidates(ballot,teamId){const team=ballot.teams[teamId];if(!team)return [];const votes=ballotVotesFor(ballot,teamId),counts=new Map(team.candidates.map(c=>[c.id,0]));votes.forEach(v=>counts.set(v.candidatePlayerId,(counts.get(v.candidatePlayerId)||0)+1));const max=Math.max(0,...counts.values());return max?team.candidates.filter(c=>counts.get(c.id)===max).map(c=>({...c,votes:max})):[]}
function buildPlayerSnapshot(player){const games=state.games.filter(g=>(g.players||[]).some(p=>p.playerId===player.id||p.name.toLocaleLowerCase('pt-BR')===player.name.toLocaleLowerCase('pt-BR'))).map(g=>{const p=g.players.find(x=>x.playerId===player.id||x.name.toLocaleLowerCase('pt-BR')===player.name.toLocaleLowerCase('pt-BR'));return {id:g.id,date:g.date,time:g.time,field:field(g.fieldId)?.name||'Gramado',maps:field(g.fieldId)?.maps||g.maps||'',waze:field(g.fieldId)?.waze||g.waze||'',fee:Number(g.fee||0),paid:!!p.paid,foodName:g.foodName||'Churrasco',foodFee:Number(p.foodWanted?g.foodFee||0:0),foodPaid:!!p.foodPaid,attendance:p.attendance||'friday',present:!!p.present,receipt:!!p.receipt,roster:(g.players||[]).map(entry=>({name:entry.name,position:entry.position==='Goleiro'?'Goleiro':'Jogador'}))}});return {name:player.name,games,pix:state.pix,updatedAt:new Date().toISOString()}}
function playerFieldLinks(game){const shared=sharedGameRosters.find(item=>item.id===game.id),known=state.fields.find(item=>playerKey(item.name)===playerKey(game.field)),maps=game.maps||shared?.maps||known?.maps||'',waze=game.waze||shared?.waze||known?.waze||'';return (maps?` · <a class="link" href="${esc(maps)}" target="_blank" rel="noopener">Google Maps ↗</a>`:'')+(waze?` · <a class="link" href="${esc(waze)}" target="_blank" rel="noopener">Waze ↗</a>`:'')}
function playerRosterPanel(game){
 if(!game)return '';
 const roster=Array.isArray(game.roster)?game.roster:[];
 const players=roster.filter(entry=>entry.position!=='Goleiro');
 const keepers=roster.filter(entry=>entry.position==='Goleiro');
 const row=(entry,label)=>'<div class="week-player"><span class="number">'+label+'</span><span>'+(entry?esc(entry.name):'<span class="subcell">Vaga aberta</span>')+'</span><small>'+(entry?esc(entry.position):'')+'</small></div>';
 const playerRows=Array.from({length:Math.max(16,players.length)},(_,index)=>row(players[index],String(index+1).padStart(2,'0'))).join('');
 const keeperRows=Array.from({length:Math.max(2,keepers.length)},(_,index)=>row(keepers[index],'G'+(index+1))).join('');
 return '<section class="panel"><div class="panel-head"><h3>Inscritos desta semana</h3><small>Ordem de inscrição · '+esc(localDate(game.date))+'</small></div><p class="sub">Todos os jogadores veem esta lista. Os nomes seguem a ordem em que foram incluídos.</p><div class="week-roster">'+playerRows+'</div><h4 style="margin:16px 0 8px">Goleiros</h4><div class="week-roster">'+keeperRows+'</div></section>';
}
function applyPlayerChoices(rows){let changed=false;for(const account of rows){if(!account.playerId||!account.attendanceChoices)continue;const player=state.players.find(x=>x.id===account.playerId);if(!player)continue;for(const [gameId,choice] of Object.entries(account.attendanceChoices)){if(!['friday','saturday'].includes(choice))continue;const game=state.games.find(g=>g.id===gameId),entry=game?.players.find(p=>p.playerId===player.id||p.name.toLocaleLowerCase('pt-BR')===player.name.toLocaleLowerCase('pt-BR'));if(entry&&entry.attendance!==choice){entry.attendance=choice;changed=true}}}if(changed)persist()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function formatPix(value){const digits=String(value||'').replace(/\D/g,'');return digits.length===11?`${digits.slice(0,2)} ${digits.slice(2,3)} ${digits.slice(3,7)} ${digits.slice(7)}`:digits}
const localDate=s=>s?new Date(`${s}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}):'';
const initials=n=>String(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function playerKey(n){return String(n||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/[^a-z0-9]/g,'')}
const phoneDigits=n=>String(n||'').replace(/\D/g,'').replace(/^55(?=\d{10,11}$)/,'');
function displayPhone(phone){const digits=String(phone||'').replace(/\D/g,'');return digits.length>=12&&digits.startsWith('55')?digits.slice(2):digits}
const playerPhoneMatches=(a,b)=>{const x=phoneDigits(a),y=phoneDigits(b);return x===y||(x.length>=9&&y.length>=9&&x.slice(-9)===y.slice(-9))};
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function fridayWindowOpen(){const weekday=new Date(`${today}T00:00:00Z`).getUTCDay();return weekday===5||weekday===6||weekday===0}
function upcoming(){const eligible=state.games.filter(g=>g.status!=='cancel'&&(fridayWindowOpen()?g.date>today:g.date>=today));return eligible.sort((a,b)=>a.date.localeCompare(b.date))[0]}
function nextWeeklyGame(game){return state.games.filter(item=>item.id!==game.id&&item.status!=='cancel'&&item.date>game.date).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function addPlayerToSuggestedTeam(game,player,position='Jogador'){
 if(!game||!player)return;
 game.teams=Array.isArray(game.teams)?game.teams:structuredClone(defaultTeams);
 const key=playerKey(player.name);
 if(position==='Goleiro'){const target=game.teams.find(team=>!team.goalkeeper||!String(team.goalkeeper).trim());if(target)target.goalkeeper=player.name;return}
 const lineCount=(game.players||[]).filter(entry=>entry.position!=='Goleiro').length;
 if(lineCount>=18&&game.teams.length<3)game.teams.push(structuredClone(thirdTeamTemplate));
 const already=game.teams.some(team=>teamPlayerNames(team).some(name=>playerKey(name)===key)||(team.playerIds||[]).includes(player.id));
 if(already)return;
 const target=game.teams.map((team,index)=>({team,index,count:teamPlayerNames(team).length})).filter(item=>item.count<6).sort((a,b)=>a.count-b.count||a.index-b.index)[0]?.team;
 if(!target)return;
 const ids=Array.isArray(target.playerIds)?target.playerIds.slice():(target.players||[]).map(name=>findTeamPlayer(name)?.id).filter(Boolean);
 target.playerIds=[...new Set([...ids,player.id])];
}
function addParticipantToGame(game,player,position='Jogador'){
 if(!game||!player)return false;
 game.players=Array.isArray(game.players)?game.players:[];
 const aliases=[player.name,player.nickname,...(player.aliases||[])].filter(Boolean).map(playerKey);
 const entry=game.players.find(item=>item.playerId===player.id||aliases.includes(playerKey(item.name)));
 if(entry){entry.name=player.name;entry.playerId=player.id;if(position==='Goleiro')entry.position='Goleiro';return false}
 game.players.push({name:player.name,playerId:player.id,position,attendance:'friday',present:false,paid:false,foodWanted:false,foodPaid:false});
 addPlayerToSuggestedTeam(game,player,position);
 return true;
}
function ensurePlayerInUpcomingGame(player){
 const game=upcoming();if(!game||!player)return false;
 const added=addParticipantToGame(game,player);
 return added;
}
function field(id){return state.fields.find(f=>f.id===id)}
function paidCount(g){return (g.players||[]).filter(p=>p.paid).length}
function dueTotal(g){return (g.players||[]).reduce((sum,p)=>sum+(p.paid?0:Number(g.fee||0))+(g.foodFee&&p.foodWanted&&!p.foodPaid?Number(g.foodFee):0),0)}
function gameStatus(g){if(g.status==='closed')return '<span class="pill done">Encerrado</span>';if(g.status==='played')return '<span class="pill done">Realizado</span>';return '<span class="pill open">Inscrições abertas</span>'}
function navItem(id,icon,label){return `<button class="${page===id?'active':''}" data-page="${id}"><span class="ico">${icon}</span>${label}</button>`}
function pageTitle(){return ({dashboard:'Visão geral',games:'Jogos',teams:'Times',players:'Participantes',fields:'Gramados',finance:'Pagamentos',polls:'Enquetes',notices:'Avisos',settings:'Configurações'})[page]||'Visão geral'}
function heading(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="sub">${esc(description)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
