function financePage(){const games=state.games.slice().sort((a,b)=>a.date.localeCompare(b.date));const selected=games.find(g=>g.id===rosterGame)||upcoming()||games[0];return `${heading('CONTROLE FINANCEIRO','Pagamentos','Confirme pagamentos recebidos por PIX e confira os valores por jogo.',`<button class="btn" data-action="export">Exportar CSV</button>`)}<div class="panel"><div class="toolbar"><label for="finance-game"><b>Jogo</b></label><select id="finance-game" class="search">${games.map(g=>`<option value="${esc(g.id)}" ${selected?.id===g.id?'selected':''}>${localDate(g.date)} · ${esc(g.time)} · ${esc(field(g.fieldId)?.name||'Gramado')}</option>`).join('')}</select><button class="btn small" data-action="copy-pix">Copiar PIX · ${esc(formatPix(state.pix))}</button></div>${selected?`<div class="payment-legend"><span>${brl(selected.fee)} por jogo${selected.foodFee?` · ${brl(selected.foodFee)} ${esc(selected.foodName||'churrasco')}`:''}</span><span>${brl(dueTotal(selected))} em aberto</span></div><div class="week-payments">${selected.players.slice().sort((a,b)=>Number(b.paid)-Number(a.paid)||(String(a.paidAt||'9999').localeCompare(String(b.paidAt||'9999')))).map(p=>{const index=selected.players.indexOf(p);return `<div class="payment-row"><div class="payment-person"><div class="avatar">${initials(p.name)}</div><div><b>${esc(p.name)}</b><small>${p.position==='Goleiro'?'Goleiro':'Jogador'}</small></div></div><button class="pill ${p.paid?'paid':'pending'}" data-action="toggle-pay" data-id="${esc(selected.id)}" data-index="${index}">Jogo ${p.paid?'pago ✓':`marcar ${brl(selected.fee)}`}</button>${selected.foodFee?(p.foodWanted?`<button class="pill ${p.foodPaid?'paid':'pending'}" data-action="toggle-food" data-id="${esc(selected.id)}" data-index="${index}">Churrasco ${p.foodPaid?'pago ✓':`marcar ${brl(selected.foodFee)}`}</button>`:'<span class="pill done">Churrasco não solicitado</span>'):''}<button class="btn small" data-action="payment" data-id="${esc(selected.id)}" data-index="${index}">Detalhes</button></div>`}).join('')||'<div class="empty">Não há participantes na lista deste jogo.</div>'}</div>`:'<div class="empty">Não há jogos cadastrados.</div>'}</div>`}
