document.addEventListener('submit',async e=>{
 if(e.target.id!=='loginForm')return;e.preventDefault();
 const form=e.target,button=e.submitter||form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Aguarde…';
 try{if(form.dataset.kind==='admin'){await signInAdmin(form.elements.email.value.trim(),form.elements.password.value)}else{const identifier=form.elements.identifier.value.trim(),firstName=identifier.split(/\s+/)[0],phone=phoneDigits(form.elements.phone.value);if(!identifier)throw new Error('Informe seu primeiro nome, nome completo ou apelido.');if(phone.length<9||phone.length>11)throw new Error('Informe o telefone com 9 dígitos, ou com DDD se preferir.');pendingPlayerIdentity={firstName,phone};if(button.value==='request')await registerPlayer(firstName,phone,identifier,'');else await signInPlayer(identifier,phone)}}
 catch(err){const adminLogin=form.dataset.kind==='admin';const message=err.code==='auth/email-already-in-use'?'Este primeiro acesso já foi solicitado. Escolha Entrar.':err.code==='auth/invalid-credential'||err.code==='auth/user-not-found'||err.code==='auth/wrong-password'?(adminLogin?'E-mail ou senha administrativa incorretos. Confirme o cadastro em Firebase Authentication → Usuários.':'Nome, apelido ou telefone incorreto. Para primeiro acesso, use o botão correspondente.'):err.code==='auth/operation-not-allowed'?'Ative o provedor E-mail/senha em Firebase Authentication → Método de login.':err.code==='auth/weak-password'?'Não foi possível cadastrar a senha.':err.message||'Não foi possível entrar. Verifique os dados.';renderLogin(message)}

});
